
begin;
create table sim_murid_private.action_plans(period_id uuid primary key references sim_murid_private.survey_periods(id),items jsonb not null,updated_by uuid not null references public.profiles(id),updated_at timestamptz not null default now());
create index action_plan_actor on sim_murid_private.action_plans(updated_by);
create table sim_murid_private.ai_configs(provider text primary key check(provider in('anthropic','gemini')),encrypted_key text not null,model text not null,updated_by uuid not null references public.profiles(id));
create index ai_config_actor on sim_murid_private.ai_configs(updated_by);
create table sim_murid_private.ai_analyses(id uuid primary key default gen_random_uuid(),period_id uuid not null references sim_murid_private.survey_periods(id),scope text not null,source_hash text not null,status text not null check(status in('running','succeeded','failed')),model text not null,result jsonb,error_code text,tokens jsonb,created_at timestamptz not null default now(),unique(period_id,scope,source_hash));
create function public.app_survey_insights(p_actor uuid,p_session uuid,p_period uuid) returns jsonb language plpgsql stable security invoker set search_path='' as $$
#variable_conflict use_variable
declare r jsonb;peer jsonb;count_r integer;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return null;end if;
 if not public.app_survey_manager(p_actor,p_session) then
 select count(*)::integer into count_r from sim_murid_private.survey_respondents r where r.period_id=p_period and r.peer_submitted_at is not null and exists(select 1 from jsonb_each(r.peer_answers->p_actor::text)x where x.key in('PTS-1','PTS-2','PTS-3','PTS-4','PTS-5','PTS-6') and jsonb_typeof(x.value)='number');
 if count_r<(select peer_min from sim_murid_private.service_settings) then return jsonb_build_object('suppressed',true,'minimum',(select peer_min from sim_murid_private.service_settings));end if;
 select jsonb_build_object('count',count_r,'dimensions',(select jsonb_object_agg(key,average) from(select x.key,round(avg((x.value#>>'{}')::numeric),2)average from sim_murid_private.survey_respondents r cross join lateral jsonb_each(r.peer_answers->p_actor::text)x where r.period_id=p_period and r.peer_submitted_at is not null and x.key<>'PTS-7' and jsonb_typeof(x.value)='number' group by x.key)z),'quotes',(select coalesce(jsonb_agg(quote),'[]') from(select r.peer_answers->p_actor::text->>'PTS-7' quote from sim_murid_private.survey_respondents r where r.period_id=p_period and r.peer_submitted_at is not null and length(btrim(r.peer_answers->p_actor::text->>'PTS-7'))>0 order by md5(r.user_id::text||p_period::text) limit 3)z)) into peer;
 return jsonb_build_object('suppressed',false,'peer',peer);end if;
 select jsonb_build_object('progress',(select coalesce(jsonb_agg(jsonb_build_object('user_id',r.user_id,'name',p.full_name,'role',r.role,'submitted_at',r.submitted_at,'revision',r.revision,'flags',r.flags,'note',r.admin_note)),'[]') from sim_murid_private.survey_respondents r join public.profiles p on p.id=r.user_id where r.period_id=p_period),'aggregates',(select coalesce(jsonb_agg(z),'[]') from(select r.role,q->>'section' section,q->>'aspect' aspect,q->>'code' code,count(*) n,round(avg((r.answers->>(q->>'code'))::numeric),2) mean from sim_murid_private.survey_respondents r cross join lateral jsonb_array_elements(r.instrument)q where r.period_id=p_period and r.submitted_at is not null and q->>'kind'='likert' and q->>'attention' is null group by r.role,q->>'section',q->>'aspect',q->>'code')z),'essays',(select coalesce(jsonb_agg(jsonb_build_object('role',r.role,'code',q->>'code','text',r.answers->>(q->>'code'),'reliability',r.flags->>'reliability')),'[]') from sim_murid_private.survey_respondents r cross join lateral jsonb_array_elements(r.instrument)q where r.period_id=p_period and r.submitted_at is not null and q->>'kind'='essay'),'analyses',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from sim_murid_private.ai_analyses a where a.period_id=p_period)) into r;return r;end$$;
create function public.app_survey_admin(p_actor uuid,p_session uuid,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
#variable_conflict use_variable
declare p sim_murid_private.survey_periods%rowtype;begin
 if p_command->>'type'='plan' then
 if not public.app_onboarding_ready(p_actor,p_session) or not public.app_education_task(p_actor,'school_head') then return jsonb_build_object('code','denied');end if;
 select * into p from sim_murid_private.survey_periods where id=(p_command->>'periodId')::uuid and status='closed';
 if not found or public.app_ops_today()<=p.ends_on or public.app_ops_today()>p.ends_on+30 or jsonb_array_length(p_command->'items') not between 3 and 7 then return jsonb_build_object('code','invalid');end if;
 if exists(select 1 from jsonb_array_elements(p_command->'items')x where x->>'aspect' not in('Pengajaran','Fasilitas','Kurikulum','Karakter','Disiplin','Budaya') or x->>'status' not in('belum','proses','selesai') or length(btrim(x->>'description'))<3 or length(btrim(x->>'owner'))<1 or (x->>'target')::date is null) then return jsonb_build_object('code','invalid');end if;
 insert into sim_murid_private.action_plans values(p.id,p_command->'items',p_actor,now()) on conflict(period_id) do update set items=excluded.items,updated_by=p_actor,updated_at=now();return jsonb_build_object('code','saved');
 elsif p_command->>'type'='note' then
 if not public.app_survey_manager(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 update sim_murid_private.survey_respondents set admin_note=p_command->>'note' where period_id=(p_command->>'periodId')::uuid and user_id=(p_command->>'userId')::uuid;return jsonb_build_object('code','saved');
 elsif p_command->>'type'='ai_config' then
 if not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 insert into sim_murid_private.ai_configs values(p_command->>'provider',p_command->>'encryptedKey',p_command->>'model',p_actor) on conflict(provider) do update set encrypted_key=excluded.encrypted_key,model=excluded.model,updated_by=p_actor;return jsonb_build_object('code','saved');
 else return jsonb_build_object('code','invalid');end if;end$$;
create function public.app_services_write(p_actor uuid,p_session uuid,p_request uuid,p_revision bigint,p_module text,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
#variable_conflict use_variable
declare old sim_murid_private.operations_requests%rowtype;v bigint;r jsonb;e sim_murid_private.point_events%rowtype;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module not in('discipline','notifications','surveys','insights','jobs') then return jsonb_build_object('code','denied');end if;
 if p_module='discipline' and not(public.app_ops_role(p_actor,'teacher') or public.app_education_admin(p_actor,p_session)) then return jsonb_build_object('code','denied');end if;
 if p_module='surveys' and p_command->>'type' in('period','close') and not public.app_survey_manager(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module='insights' and p_command->>'type'='ai_config' and not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module='insights' and p_command->>'type'='plan' and not public.app_education_task(p_actor,'school_head') then return jsonb_build_object('code','denied');end if;
 if p_module='insights' and p_command->>'type'='note' and not public.app_survey_manager(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module='jobs' and not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 select revision into v from sim_murid_private.operations_state for update;
 select * into old from sim_murid_private.operations_requests where id=p_request;if found then if old.actor=p_actor and old.module='services:'||p_module and old.command=p_command then return old.result;end if;return jsonb_build_object('code','request_conflict');end if;
 if v is distinct from p_revision then return jsonb_build_object('code','stale');end if;
 if p_module='discipline' then
 if p_command->>'type' in('event','cancel','catalog') then r=public.app_point_mutate(p_actor,p_session,p_command);else r=public.app_point_admin(p_actor,p_session,p_command);end if;
 if r->>'code'='saved' and p_command->>'type'='event' then select * into e from sim_murid_private.point_events where id=(r->>'id')::uuid;perform public.app_point_notify(e.student_id,date_trunc('month',e.event_date)::date,e.id);end if;
 elsif p_module='notifications' then update sim_murid_private.inbox set read_at=coalesce(read_at,now()) where recipient_id=p_actor and(p_command->>'id' is null or id=(p_command->>'id')::uuid);r=jsonb_build_object('code','saved');
 elsif p_module='surveys' then r=public.app_survey_mutate(p_actor,p_session,p_command);
 elsif p_module='insights' then r=public.app_survey_admin(p_actor,p_session,p_command);
 elsif p_module='jobs' then r=public.app_jobs_admin(p_actor,p_session,p_command);
 end if;
 if r->>'code'='saved' then update sim_murid_private.operations_state set revision=revision+1;
 insert into sim_murid_private.operations_requests(id,actor,module,command,result) values(p_request,p_actor,'services:'||p_module,p_command,r);
 insert into sim_murid_private.activity_logs(actor_id,actor_kind,action,entity_type,entity_id,request_id,metadata) values(p_actor,'user',p_module||'.'||(p_command->>'type'),p_module,(r->>'id')::uuid,p_request,jsonb_build_object('command',p_command-'encryptedKey','result',r-'response'));end if;return r;
exception when unique_violation then return jsonb_build_object('code','duplicate');when invalid_text_representation or check_violation or not_null_violation or foreign_key_violation or datetime_field_overflow or numeric_value_out_of_range then return jsonb_build_object('code','invalid');end$$;
create function public.app_services_read(p_actor uuid,p_session uuid,p_module text,p_filters jsonb default '{}') returns jsonb language plpgsql stable security invoker set search_path='' as $$
#variable_conflict use_variable
declare result jsonb:='[]';extra jsonb:='{}';mo date;period uuid;cls uuid;sid uuid;manager boolean;admin boolean;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return null;end if;
 admin=public.app_education_admin(p_actor,p_session);manager=public.app_survey_manager(p_actor,p_session);mo=coalesce((p_filters->>'month')::date,date_trunc('month',public.app_ops_today())::date);period=(p_filters->>'periodId')::uuid;cls=(p_filters->>'classId')::uuid;sid=(p_filters->>'studentId')::uuid;
 if mo<>date_trunc('month',mo)::date then return null;end if;
 if p_module='discipline' then
 select coalesce(jsonb_agg(jsonb_build_object('student_id',p.id,'name',p.full_name,'class_id',e.class_id,'class_name',c.name,'snapshot',coalesce(s.snapshot,public.app_point_replay(p.id,mo)),'archived',s.student_id is not null) order by p.full_name),'[]') into result from public.profiles p join public.user_roles r on r.user_id=p.id join sim_murid_private.enrollments e on e.student_id=p.id join public.classes c on c.id=e.class_id join public.academic_years y on y.id=e.academic_year_id left join sim_murid_private.point_month_snapshots s on s.student_id=p.id and s.month=mo where mo>=make_date(y.start_year,7,1) and mo<make_date(y.start_year+1,7,1) and(cls is null or cls=e.class_id) and(sid is null or sid=p.id) and public.app_point_access(p_actor,p_session,p.id);
 extra=jsonb_build_object('catalog',(select jsonb_agg(c order by code) from sim_murid_private.point_catalog c),'settings',(select to_jsonb(s) from sim_murid_private.service_settings s),'canRecord',admin or public.app_ops_role(p_actor,'teacher'),'affective',(select coalesce(jsonb_agg(a),'[]') from sim_murid_private.affective_scores a where a.month=mo and public.app_point_access(p_actor,p_session,a.student_id)));
 -- Rankings are calculated from exactly the scoped, filtered snapshots.
 extra=extra||jsonb_build_object('ranking',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(public.app_point_ranking(mo))x where public.app_point_access(p_actor,p_session,(x#>>'{x,student_id}')::uuid) and(cls is null or (x#>>'{x,class_id}')::uuid=cls) and(sid is null or(x#>>'{x,student_id}')::uuid=sid)));
 elsif p_module='notifications' then select coalesce(jsonb_agg(i order by created_at desc),'[]') into result from(select id,title,message,entity_id,read_at,created_at from sim_murid_private.inbox where recipient_id=p_actor order by created_at desc limit 200)i;extra=jsonb_build_object('unread',(select count(*) from sim_murid_private.inbox where recipient_id=p_actor and read_at is null));
 elsif p_module='surveys' then
 select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('response',(select to_jsonb(r)-'admin_note' from sim_murid_private.survey_respondents r where r.period_id=p.id and r.user_id=p_actor),'plan',(select items from sim_murid_private.action_plans where period_id=p.id)) order by p.starts_on desc),'[]') into result from sim_murid_private.survey_periods p where manager or exists(select 1 from public.user_roles where user_id=p_actor and role_code=any(p.targets));
 extra=jsonb_build_object('required',(select coalesce(jsonb_agg(p.id),'[]') from sim_murid_private.survey_periods p join public.user_roles ur on ur.user_id=p_actor and ur.role_code=any(p.targets) where p.kind='main' and public.app_survey_open(p.id) and not exists(select 1 from sim_murid_private.survey_respondents r where r.period_id=p.id and r.user_id=p_actor and r.submitted_at is not null)),'peers',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name)),'[]') from public.profiles p where p.id in(select unnest(peers) from sim_murid_private.survey_respondents where user_id=p_actor and(period is null or period_id=period))));
 elsif p_module='insights' then extra=coalesce(public.app_survey_insights(p_actor,p_session,period),'{}');
 if manager then select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'start',starts_on,'end',ends_on,'kind',kind,'status',status,'version',instrument_version) order by starts_on desc),'[]') into result from sim_murid_private.survey_periods;extra=extra||jsonb_build_object('configs',(select coalesce(jsonb_agg(jsonb_build_object('provider',provider,'model',model,'configured',true)),'[]') from sim_murid_private.ai_configs),'canPlan',public.app_education_task(p_actor,'school_head'),'trend',(select coalesce(jsonb_agg(z),'[]') from(select r.period_id,r.role,q->>'aspect' aspect,count(*) n,round(avg((r.answers->>(q->>'code'))::numeric),2) mean from sim_murid_private.survey_respondents r cross join lateral jsonb_array_elements(r.instrument)q where r.submitted_at is not null and q->>'kind'='likert' and q->>'attention' is null group by r.period_id,r.role,q->>'aspect')z));end if;
 elsif p_module='jobs' then if not admin then return null;end if;select coalesce(jsonb_agg(to_jsonb(o)-'payload' order by created_at desc),'[]') into result from(select * from sim_murid_private.outbox order by created_at desc limit 200)o;extra=jsonb_build_object('jobs',(select coalesce(jsonb_agg(j order by created_at desc),'[]') from(select * from sim_murid_private.job_runs order by created_at desc limit 100)j));
 elsif p_module='reconciliation' then if not admin then return null;end if;extra=jsonb_build_object('tables',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','sim_murid_private') and c.relkind='r'),'savingsBalance',(select coalesce(sum(delta),0) from sim_murid_private.savings_transactions),'reportSnapshots',(select count(*) from sim_murid_private.report_snapshots),'pointSnapshots',(select count(*) from sim_murid_private.point_month_snapshots),'submittedSurveys',(select count(*) from sim_murid_private.survey_respondents where submitted_at is not null),'sourceAvailable',false);
 else return null;end if;
 return jsonb_build_object('module',p_module,'revision',(select revision from sim_murid_private.operations_state),'today',public.app_ops_today(),'isAdmin',admin,'isManager',manager,'month',mo,'rows',result,'extra',extra,'years',(select jsonb_agg(jsonb_build_object('id',id,'start_year',start_year)) from public.academic_years),'classes',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name)),'[]') from public.classes c where admin or public.app_ops_role(p_actor,'teacher') or exists(select 1 from sim_murid_private.enrollments e where e.class_id=c.id and public.app_ops_student(p_actor,p_session,e.student_id))),'subjects',(select jsonb_agg(jsonb_build_object('id',id,'name',name)) from public.subjects where active));end$$;
do $$declare t text;r record;begin foreach t in array array['action_plans','ai_configs','ai_analyses'] loop execute format('alter table sim_murid_private.%I enable row level security',t);execute format('revoke all on sim_murid_private.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on sim_murid_private.%I to service_role',t);end loop;for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'app_services_%' or p.proname in('app_survey_insights','app_survey_admin')) loop execute format('revoke all on function %s from public,anon,authenticated',r.signature);execute format('grant execute on function %s to service_role',r.signature);end loop;end$$;
commit;
